function(data, prefix) {
    output <- dplyr::summarise(dplyr::group_by(data, .data$site), participants = dplyr::n_distinct(.data$Id), participant_days = dplyr::n_distinct(paste(.data$Id, .data$local_date)), grid_rows = dplyr::n(), admissible_rows = sum(.data$bin_admissible %in% TRUE), .groups = "drop")
    names(output)[-1] <- paste(prefix, names(output)[-1], sep = "_")
    output
}

function(metric_column, placement_label) {
    metric_participants <- participant_availability[[metric_column]] %in% TRUE
    matching_counts <- vapply(unname(modality_columns), function(column) {
        sum(participant_availability[[column]][metric_participants] %in% TRUE)
    }, integer(1))
    tibble::tibble(Placement = placement_label, `Questionnaire or diary input` = names(modality_columns), `Participants with light metrics` = sum(metric_participants), `Participants with matching input` = matching_counts, `Participants without matching input` = sum(metric_participants) - matching_counts)
}

