function(value) {
    gsub(">", "&gt;", x = gsub("<", "&lt;", x = gsub("\"", "&quot;", x = gsub("&", "&amp;", x = value, fixed = TRUE), fixed = TRUE), fixed = TRUE), fixed = TRUE)
}

function(p_value, supported) {
    display <- format_p(p_value)
    statement <- if (is.finite(p_value) && p_value < 0.001) {
        paste0("FDR-adjusted p ", gsub("<", "&lt;", display, fixed = TRUE))
    }
    else {
        paste0("FDR-adjusted p = ", display)
    }
    if (isTRUE(supported)) 
        paste0("**", statement, "**")
    else statement
}

function(estimate, conf_low, conf_high, supported) {
    statement <- paste0("Part R²: ", format_r2(estimate, conf_low, conf_high))
    if (isTRUE(supported)) {
        statement
    }
    else {
        paste0("<span style='color:#666'>", statement, " (not FDR-supported)</span>")
    }
}

function(p_value, supported, part_estimate, part_low, part_high, effect = NULL, effect_label = NULL) {
    lines <- c(if (isTRUE(supported)) "Supported" else "Not supported", if (!is.null(effect)) paste0(effect_label, ": ", effect), format_fdr_statement(p_value, supported), format_part_r2_statement(part_estimate, part_low, part_high, supported))
    paste(lines, collapse = "<br>")
}

function(path, metric_name) {
    image <- gt::local_image(file.path(root, path), height = 150)
    alt <- paste("Ridgeline density distributions for", metric_name, "across the nine study sites in registered north-to-south order.")
    paste0("<span class=\"h01-density-thumbnail\" role=\"img\" aria-label=\"", escape_html_attribute(alt), "\">", image, "</span>")
