    stopifnot(nrow(row) == 1L)
    comparison <- if (identical(activity_code, "home")) {
        "reference category"
    }
    else {
        paste0("ratio to At home ", format_ratio_ci(row$ratio_to_home, row$ratio_conf_low, row$ratio_conf_high))
    }
    paste0("**", unname(reader_activity_labels[[activity_code]]), ":** ", format_mean_ci(row$standardized_mean_lx, row$mean_conf_low_lx, row$mean_conf_high_lx), " lx; ", comparison, ".")
}

