function(value, significant = FALSE) {
    displayed <- ifelse(is.na(value), "—", ifelse(value < 0.001, "<0.001", sprintf("%.3f", value)))
    ifelse(significant & !is.na(value), paste0("**", displayed, "**"), displayed)
}

