function(estimate, low, high, type, unit, digits = 3L) {
    if (type == "odds_ratio") {
        return(paste0("OR ", format_number(estimate, digits), " (", format_number(low, digits), "–", format_number(high, digits), ")"))
    }
    if (type == "ratio") {
        return(paste0("×", format_number(estimate, digits), " (", format_number(low, digits), "–", format_number(high, digits), ")"))
    }
    suffix <- if (unit %in% c("h", "clock time")) 
        " h"
    else ""
    paste0(sprintf(paste0("%+.", digits, "f"), estimate), suffix, " (", sprintf(paste0("%+.", digits, "f"), low), "–", sprintf(paste0("%+.", digits, "f"), high), suffix, ")")
}

