function(estimate, lower, upper, uses_interaction, site_minimum, site_maximum, association_q, interaction_q) {
    model_text <- ifelse(uses_interaction, "Interaction model: site-average full contrast", "Additive model: common contrast")
    site_text <- ifelse(uses_interaction, sprintf("<br><small>Full site-specific ratios: %.2f to %.2f</small>", site_minimum, site_maximum), "")
    paste0("**", model_text, "**<br>", sprintf("%.2f times (%.2f to %.2f)", estimate, lower, upper), site_text, "<br><small>Additive-family association q = ", format_p(association_q), "; global site-interaction q = ", format_p(interaction_q), "</small>")
}

