function(work_free_day, activity_status) {
    work_free_day <- as.character(work_free_day)
    activity_status <- as.character(activity_status)
    activity_short <- ifelse(grepl("^Sedentary", activity_status), "Sedentary", ifelse(grepl("^Active", activity_status), "Active", NA_character_))
    group <- paste(work_free_day, activity_short, sep = " · ")
    invalid <- is.na(work_free_day) | is.na(activity_short) | !group %in% h06_day_activity_levels()
    if (any(invalid)) {
        h06_abort(paste("The exploratory time-of-day model received an unsupported", "work/free-day or activity-status value"))
    }
    factor(group, levels = h06_day_activity_levels())
}

function(k = 12L, random_effects = TRUE) {
    if (length(k) != 1L || !is.finite(k) || k < 5L || k != as.integer(k)) {
        h06_abort("The exploratory two-part GAM basis dimension must be one integer >= 5")
    }
    terms <- c("site", "work_free_day * activity_status", sprintf(paste0("s(clock_hour, by = day_activity_group, bs = 'cc', ", "k = %d, id = 1)"), as.integer(k)))
    if (isTRUE(random_effects)) {
        terms <- c(terms, "s(participant_key, bs = 're')", "s(participant_day_key, bs = 're')")
    }
    paste(terms, collapse = " + ")
}

function(k = 12L) {
    smooth_terms <- h06_exploratory_two_part_gamm_terms(k = k, random_effects = TRUE)
    make_formula <- function(response) {
        stats::as.formula(paste(response, "~ previous_sleep_duration_centered_h +", smooth_terms))
    }
    list(occurrence = make_formula("melEDI_positive"), positive_magnitude = make_formula("response_value"))
}

