function() {
    formulas <- h06_formula_set()
    exploratory <- h06_exploratory_formula_set()
    runs <- h06_run_registry()
    families <- h06_multiplicity_registry()
    formula_text <- vapply(formulas, function(x) paste(deparse(x), collapse = " "), character(1))
    if (length(formulas) != 10L || length(exploratory) != 5L || nrow(runs) != 6L || nrow(families) != 5L || any(families$planned_size != 3L) || any(grepl("\\|", formula_text)) || any(grepl("ar1", formula_text, fixed = TRUE)) || any(grepl("clock_hour", formula_text, fixed = TRUE)) || any(grepl("exercise_intensity", formula_text, fixed = TRUE))) {
        h06_abort("The H06 Stage 2 contract is internally inconsistent")
    }
    invisible(TRUE)
}

