function(environment, project_dir) {
    list_file <- environment_value(environment, "QUARTO_USE_FILE_FOR_PROJECT_OUTPUT_FILES")
    if (nzchar(list_file)) {
        list_path <- resolve_path(list_file, project_dir, must_work = TRUE)
        assert_condition(file.exists(list_path) && !dir.exists(list_path), "The Quarto output-list indirection path must be an existing file.")
        outputs <- readLines(list_path, warn = FALSE, encoding = "UTF-8")
    }
    else {
        output_value <- environment_value(environment, "QUARTO_PROJECT_OUTPUT_FILES")
        assert_condition(nzchar(output_value), paste0("QUARTO_PROJECT_OUTPUT_FILES is missing and no output-list ", "indirection file was declared."))
        outputs <- strsplit(output_value, "\n", fixed = TRUE)[[1L]]
    }
    outputs <- sub("\r$", "", outputs)
    assert_condition(length(outputs) > 0L && all(nzchar(outputs)), "The declared Quarto output list must contain only nonempty paths.")
    assert_condition(!anyDuplicated(outputs), "The declared Quarto output list contains duplicate paths.")
    outputs
}

function(environment, project_dir) {
    audit_value <- environment_value(environment, "GT_HTML_SEMANTIC_AUDIT_DIR")
    if (!nzchar(audit_value)) {
        return(NULL)
    }
    assert_condition(is_absolute_path(audit_value), "GT_HTML_SEMANTIC_AUDIT_DIR must be an absolute path.")
    audit_dir <- normalizePath(audit_value, winslash = "/", mustWork = TRUE)
    assert_condition(dir.exists(audit_dir), "GT_HTML_SEMANTIC_AUDIT_DIR must be an existing directory.")
    assert_condition(!path_is_within(audit_dir, project_dir), paste0("GT_HTML_SEMANTIC_AUDIT_DIR must resolve outside the project and ", "output trees."))
    audit_dir
}

function(outputs, context) {
    normalized <- vapply(outputs, function(path) {
        candidate <- if (is_absolute_path(path)) {
            path
        }
        else {
            file.path(context$project_dir, path)
        }
        assert_condition(file.exists(candidate) && !dir.exists(candidate), paste0("Declared Quarto output does not exist as a file: ", path))
        resolved <- normalizePath(candidate, winslash = "/", mustWork = TRUE)
        assert_condition(path_is_within(resolved, context$output_dir) && !identical(resolved, context$output_dir), paste0("Declared Quarto output resolves outside _build/nathealth: ", path))
        resolved
    }, character(1))
    assert_condition(!anyDuplicated(normalized), "Declared Quarto outputs resolve to duplicate files.")
    data.frame(declared_path = outputs, normalized_path = unname(normalized), project_relative_path = substring(unname(normalized), nchar(context$project_dir) + 2L), is_html = tolower(tools::file_ext(unname(normalized))) %in% c("html", "htm"), stringsAsFactors = FALSE)
}

function(path, engine) {
    input_raw <- engine$read_file_raw(path)
    input_sha256 <- engine$sha256_raw(input_raw)
    document <- read_html(rawToChar(input_raw))
    tables <- xml_find_all(document, gt_table_xpath)
    if (length(tables) == 0L) {
        return(list(disposition = "NO_GT", sha256 = input_sha256, bytes = length(input_raw), table_count = 0L, id_count = 0L, headers_count = 0L))
    }
    endpoints <- vapply(tables, function(table) {
        endpoint <- xml_find_first(table, "ancestor::*[@id and starts-with(@id,'tbl-')][1]")
        assert_condition(!inherits(endpoint, "xml_missing"), "Every native gt table must have one Quarto tbl-* endpoint.")
        xml_attr(endpoint, "id")
    }, character(1))
    assert_condition(all(nzchar(endpoints)) && !anyDuplicated(endpoints), "Native gt table endpoints must be nonempty and document-unique.")
    complete <- logical(length(tables))
    namespace_marker <- logical(length(tables))
    id_count <- integer(length(tables))
    headers_count <- integer(length(tables))
    for (i in seq_along(tables)) {
        table <- tables[[i]]
        id_nodes <- xml_find_all(table, "self::*[@id] | .//*[@id]")
        ids <- xml_attr(id_nodes, "id")
        header_nodes <- xml_find_all(table, "self::*[@headers] | .//*[@headers]")
        header_values <- xml_attr(header_nodes, "headers")
        header_tokens <- unlist(strsplit(header_values, "[[:space:]]+"), use.names = FALSE)
        assert_condition(length(ids) > 0L && !anyNA(ids) && all(nzchar(ids)), "Every native gt table must have nonempty internal IDs.")
        assert_condition(!anyDuplicated(ids), "A native gt table contains duplicate internal IDs.")
        id_count[[i]] <- length(ids)
        headers_count[[i]] <- length(header_values)
        expected_ids <- sprintf("%s--gt-%04d", endpoints[[i]], seq_along(ids))
        marker_values <- c(ids, header_tokens)
        namespace_marker[[i]] <- any(grepl("^tbl-.*--gt-[0-9]{4}$", marker_values, perl = TRUE))
        headers_complete <- all(vapply(header_values, function(value) {
            tokens <- strsplit(value, "[[:space:]]+")[[1L]]
            positions <- match(tokens, ids)
            length(tokens) > 0L && !anyNA(positions) && all(vapply(tokens, function(token) sum(ids == token) == 1L, logical(1))) && all(xml_name(id_nodes[positions]) == "th") && all(xml_attr(id_nodes[positions], "scope") %in% c("col", "row", "colgroup", "rowgroup"))
        }, logical(1)))
        complete[[i]] <- identical(unname(ids), unname(expected_ids)) && headers_complete
    }
    if (all(complete)) {
        document_ids <- xml_attr(xml_find_all(document, ".//*[@id]"), "id")
        document_ids <- document_ids[!is.na(document_ids) & nzchar(document_ids)]
        all_internal_ids <- unlist(lapply(tables, function(table) {
            xml_attr(xml_find_all(table, "self::*[@id] | .//*[@id]"), "id")
        }))
        unsupported <- engine$inventory_unsupported_id_references(document, all_internal_ids)
        assert_condition(!anyDuplicated(document_ids) && nrow(unsupported) == 0L, paste0("A namespaced gt document has duplicate IDs or unsupported ", "internal-ID references."))
        return(list(disposition = "ALREADY_REPAIRED", sha256 = input_sha256, bytes = length(input_raw), table_count = length(tables), id_count = sum(id_count), headers_count = sum(headers_count)))
    }
    assert_condition(!any(namespace_marker), paste0("Native gt HTML is partially namespaced or otherwise ambiguous; ", "no repair was attempted."))
    list(disposition = "UNREPAIRED", sha256 = input_sha256, bytes = length(input_raw), table_count = length(tables), id_count = sum(id_count), headers_count = sum(headers_count))
}

