function(target, disposition, pre_sha256 = NA_character_, post_sha256 = NA_character_, pre_bytes = NA_real_, post_bytes = NA_real_, table_count = 0L, id_count = 0L, headers_count = 0L, total_substitutions = 0L, ledger_file = "") {
    data.frame(target = target, disposition = disposition, pre_sha256 = pre_sha256, post_sha256 = post_sha256, pre_bytes = pre_bytes, post_bytes = post_bytes, table_count = as.integer(table_count), id_count = as.integer(id_count), headers_count = as.integer(headers_count), total_substitutions = as.integer(total_substitutions), ledger_file = ledger_file, stringsAsFactors = FALSE)
}

function(environment, project_dir = getwd(), .finalize_callback = NULL) {
    context <- validate_project_context(environment, project_dir)
    audit_dir <- validate_audit_directory(environment, context$project_dir)
    declared <- read_declared_output_files(environment, context$project_dir)
    outputs <- normalize_declared_outputs(declared, context)
    engine <- load_repair_engine(context$project_dir)
    temporary_root <- normalizePath(tempdir(), winslash = "/", mustWork = TRUE)
    assert_condition(!path_is_within(temporary_root, context$project_dir), "The R temporary directory must resolve outside the project tree.")
    staging_dir <- tempfile("gt-html-post-render-stage-", temporary_root)
    dir.create(staging_dir)
    staging_dir <- normalizePath(staging_dir, winslash = "/", mustWork = TRUE)
    assert_condition(path_is_within(staging_dir, temporary_root), "The staging directory did not resolve inside the R temporary directory.")
    on.exit({
        if (dir.exists(staging_dir) && path_is_within(staging_dir, temporary_root)) {
            unlink(staging_dir, recursive = TRUE, force = TRUE)
        }
    }, add = TRUE)
    plans <- list()
    rows <- list()
    for (i in seq_len(nrow(outputs))) {
        target <- outputs$project_relative_path[[i]]
        path <- outputs$normalized_path[[i]]
        if (!outputs$is_html[[i]]) {
            rows[[i]] <- build_summary_row(target = target, disposition = "IGNORED_NON_HTML")
            next
        }
        state <- inspect_gt_html_state(path, engine)
        if (state$disposition == "NO_GT") {
            rows[[i]] <- build_summary_row(target = target, disposition = "NO_GT", pre_sha256 = state$sha256, post_sha256 = state$sha256, pre_bytes = state$bytes, post_bytes = state$bytes)
            next
        }
        if (state$disposition == "ALREADY_REPAIRED") {
            rows[[i]] <- build_summary_row(target = target, disposition = "ALREADY_REPAIRED", pre_sha256 = state$sha256, post_sha256 = state$sha256, pre_bytes = state$bytes, post_bytes = state$bytes, table_count = state$table_count, id_count = state$id_count, headers_count = state$headers_count)
            next
        }
        staged_output <- file.path(staging_dir, sprintf("%03d-output.html", i))
        staged_ledger <- file.path(staging_dir, sprintf("%03d-ledger.csv", i))
        repair <- engine$repair_gt_html_semantics(path, staged_output, staged_ledger)
        repaired_state <- inspect_gt_html_state(staged_output, engine)
        assert_condition(repaired_state$disposition == "ALREADY_REPAIRED", "A staged gt HTML repair did not satisfy the complete postcondition.")
        original_raw <- engine$read_file_raw(path)
        repaired_raw <- engine$read_file_raw(staged_output)
        mode <- file.info(path)$mode[[1L]]
        plans[[length(plans) + 1L]] <- list(output_index = i, target = target, path = path, original_raw = original_raw, repaired_raw = repaired_raw, mode = mode, staged_ledger = staged_ledger, repair = repair)
        rows[[i]] <- build_summary_row(target = target, disposition = "REPAIRED", pre_sha256 = repair$input_sha256, post_sha256 = repair$output_sha256, pre_bytes = repair$input_bytes, post_bytes = repair$output_bytes, table_count = repair$table_count, id_count = repair$id_substitutions, headers_count = repair$headers_substitutions, total_substitutions = repair$total_substitutions)
    }
    summary <- do.call(rbind, rows)
    rownames(summary) <- NULL
    staged_audit <- list()
    if (!is.null(audit_dir)) {
        summary_destination <- file.path(audit_dir, "gt_html_semantic_post_render_summary.csv")
        assert_condition(!file.exists(summary_destination), "The external combined audit-summary destination already exists.")
        summary_stage <- file.path(staging_dir, "combined-summary.csv")
        write.csv(summary, summary_stage, row.names = FALSE, na = "")
        staged_audit[[length(staged_audit) + 1L]] <- list(staged = summary_stage, destination = summary_destination)
        for (plan_index in seq_along(plans)) {
            plan <- plans[[plan_index]]
            ledger_name <- sprintf("%03d_%s_gt_semantic_ledger.csv", plan$output_index, safe_audit_stem(plan$target))
            ledger_destination <- file.path(audit_dir, ledger_name)
            assert_condition(!file.exists(ledger_destination), paste0("External audit-ledger destination already exists: ", ledger_name))
            staged_audit[[length(staged_audit) + 1L]] <- list(staged = plan$staged_ledger, destination = ledger_destination)
            summary$ledger_file[[plan$output_index]] <- ledger_name
        }
        write.csv(summary, summary_stage, row.names = FALSE, na = "")
    }
    if (is.null(.finalize_callback)) {
        .finalize_callback <- function(path, index) invisible(NULL)
    }
    assert_condition(is.function(.finalize_callback), "The finalization callback must be a function.")
    touched <- list()
    created_audit <- character()
    finalization_error <- NULL
    tryCatch({
        for (plan_index in seq_along(plans)) {
            plan <- plans[[plan_index]]
            touched[[length(touched) + 1L]] <- plan
            write_raw_exact(plan$repaired_raw, plan$path)
            Sys.chmod(plan$path, mode = plan$mode)
            .finalize_callback(plan$path, plan_index)
            assert_condition(identical(engine$read_file_raw(plan$path), plan$repaired_raw), paste0("Finalized HTML does not match its staged repair: ", plan$target))
        }
        for (audit_plan in staged_audit) {
            copied <- file.copy(audit_plan$staged, audit_plan$destination, overwrite = FALSE, copy.mode = TRUE)
            assert_condition(isTRUE(copied), paste0("Could not finalize external audit file: ", basename(audit_plan$destination)))
            created_audit <- c(created_audit, audit_plan$destination)
        }
    }, error = function(error) {
        finalization_error <<- error
    })
    if (!is.null(finalization_error)) {
        rollback_errors <- character()
        for (plan in rev(touched)) {
            rollback_result <- tryCatch({
                write_raw_exact(plan$original_raw, plan$path)
                Sys.chmod(plan$path, mode = plan$mode)
                assert_condition(identical(engine$read_file_raw(plan$path), plan$original_raw), paste0("Rollback verification failed for ", plan$target))
                NULL
            }, error = conditionMessage)
            if (!is.null(rollback_result)) {
                rollback_errors <- c(rollback_errors, rollback_result)
            }
        }
        for (audit_path in created_audit) {
            if (file.exists(audit_path)) {
                unlink(audit_path)
            }
        }
        assert_condition(length(rollback_errors) == 0L, paste0("Post-render finalization failed and rollback was incomplete: ", paste(rollback_errors, collapse = "; ")))
        stop(paste0("Post-render finalization failed; exact originals were restored: ", conditionMessage(finalization_error)), call. = FALSE)
    }
    summary
}

function(summary) {
