function(x, start, end) {
    if (end < start) {
        return("")
    }
    rawToChar(x[start:end])
}

function(pattern, text) {
    matches <- gregexpr(pattern, text, perl = TRUE, useBytes = TRUE)[[1L]]
    if (identical(matches[[1L]], -1L)) {
        return(data.frame(start = integer(), length = integer()))
    }
    data.frame(start = as.integer(matches), length = as.integer(attr(matches, "match.length")))
}

function(input_raw) {
    text <- rawToChar(input_raw)
    tags <- regex_matches_bytes("(?i)<table\\b[^>]*>|</table\\s*>", text)
    stopifnot(nrow(tags) > 0L)
    tag_text <- vapply(seq_len(nrow(tags)), function(i) {
        raw_slice_text(input_raw, tags$start[[i]], tags$start[[i]] + tags$length[[i]] - 1L)
    }, character(1))
    stack <- list()
    ranges <- list()
    for (i in seq_len(nrow(tags))) {
        current <- tag_text[[i]]
        if (grepl("(?i)^<table\\b", current, perl = TRUE)) {
            class_match <- regexec("(?i)\\bclass=\"([^\"]*)\"", current, perl = TRUE, useBytes = TRUE)
            class_parts <- regmatches(current, class_match)[[1L]]
            classes <- if (length(class_parts) == 2L) {
                strsplit(class_parts[[2L]], "[[:space:]]+")[[1L]]
            }
            else {
                character()
            }
            stack[[length(stack) + 1L]] <- list(start = tags$start[[i]], open_end = tags$start[[i]] + tags$length[[i]] - 1L, is_gt = "gt_table" %in% classes)
        }
        else {
            stopifnot(length(stack) > 0L)
            opened <- stack[[length(stack)]]
            stack <- stack[-length(stack)]
            if (opened$is_gt) {
                ranges[[length(ranges) + 1L]] <- data.frame(start = opened$start, open_end = opened$open_end, end = tags$start[[i]] + tags$length[[i]] - 1L)
            }
        }
    }
    stopifnot(length(stack) == 0L, length(ranges) > 0L)
    ranges <- do.call(rbind, ranges)
    ranges[order(ranges$start), , drop = FALSE]
}

function(input_raw, table_start, table_end, name) {
    table_text <- raw_slice_text(input_raw, table_start, table_end)
    pattern <- paste0("(?<![[:alnum:]_-])", name, "=\"[^\"]*\"")
    matches <- regex_matches_bytes(pattern, table_text)
    if (nrow(matches) == 0L) {
        return(data.frame(value_start_byte = integer(), value_end_byte = integer(), value = character()))
    }
    prefix_bytes <- nchar(paste0(name, "=\""), type = "bytes")
    value_start <- table_start - 1L + matches$start + prefix_bytes
    value_end <- table_start - 1L + matches$start + matches$length - 2L
    value <- vapply(seq_len(nrow(matches)), function(i) {
        raw_slice_text(input_raw, value_start[[i]], value_end[[i]])
    }, character(1))
    data.frame(value_start_byte = value_start, value_end_byte = value_end, value = value, stringsAsFactors = FALSE)
}

function(node, class_name) {
    classes <- xml_attr(node, "class")
    !is.na(classes) && class_name %in% strsplit(classes, "[[:space:]]+")[[1L]]
}

function(table) {
    id_nodes <- xml_find_all(table, "self::*[@id] | .//*[@id]")
    ids <- xml_attr(id_nodes, "id")
    stopifnot(length(ids) > 0L, !anyNA(ids), all(nzchar(ids)), !anyDuplicated(ids))
    group_nodes <- id_nodes[vapply(id_nodes, function(node) {
        class_has(node, "gt_group_heading") || class_has(node, "gt_stub_row_group")
    }, logical(1))]
    group_ids <- unique(xml_attr(group_nodes, "id"))
    group_ids <- group_ids[!is.na(group_ids) & nzchar(group_ids)]
    list(id_nodes = id_nodes, ids = ids, group_ids = group_ids)
}

function(value, table, metadata) {
    value <- normalize_space(value)
    ids <- metadata$ids
    stub_match <- regexpr("stub_[0-9]+_[0-9]+", value, perl = TRUE)
    if (stub_match[[1L]] > 0L) {
        start <- stub_match[[1L]]
        length <- attr(stub_match, "match.length")
        row_id <- substr(value, start, start + length - 1L)
        group_raw <- normalize_space(substr(value, 1L, start - 1L))
        column_raw <- normalize_space(substr(value, start + length, nchar(value)))
        refs <- c(if (nzchar(group_raw)) group_raw, row_id, if (nzchar(column_raw)) valid_html_id_gt_1_3_0(column_raw))
    }
    else {
        direct <- valid_html_id_gt_1_3_0(value)
        if (direct %in% ids) {
            refs <- direct
        }
        else {
            solutions <- list()
            for (group_id in metadata$group_ids) {
                prefix <- paste0(group_id, " ")
                if (startsWith(value, prefix)) {
                  column_raw <- substring(value, nchar(prefix) + 1L)
                  candidate <- c(group_id, valid_html_id_gt_1_3_0(column_raw))
                  if (all(candidate %in% ids)) {
                    solutions[[length(solutions) + 1L]] <- candidate
                  }
                }
            }
            stopifnot(length(solutions) == 1L)
            refs <- solutions[[1L]]
        }
    }
    stopifnot(length(refs) > 0L, !anyDuplicated(refs), all(refs %in% ids))
    ref_nodes <- metadata$id_nodes[match(refs, ids)]
    stopifnot(all(xml_name(ref_nodes) == "th"), all(xml_attr(ref_nodes, "scope") %in% c("col", "row", "colgroup", "rowgroup")))
    refs
}

function(doc, old_ids) {
    idref_attributes <- c("aria-labelledby", "aria-describedby", "aria-controls", "aria-owns", "aria-flowto", "aria-activedescendant", "aria-details", "aria-errormessage", "for", "list", "form", "itemref")
    findings <- list()
    all_nodes <- xml_find_all(doc, ".//*")
    for (node in all_nodes) {
        attributes <- xml_attrs(node)
        if (length(attributes) == 0L) {
            next
        }
        for (attribute in intersect(names(attributes), idref_attributes)) {
            value <- attributes[[attribute]]
            tokens <- strsplit(normalize_space(value), "[[:space:]]+")[[1L]]
            referenced <- unique(c(old_ids[old_ids == value], intersect(tokens, old_ids)))
            if (length(referenced) > 0L) {
                findings[[length(findings) + 1L]] <- data.frame(element = xml_name(node), attribute = attribute, value = value, referenced_ids = paste(referenced, collapse = "|"), stringsAsFactors = FALSE)
            }
        }
        for (attribute in intersect(names(attributes), c("href", "xlink:href"))) {
            value <- attributes[[attribute]]
            if (startsWith(value, "#") && substring(value, 2L) %in% old_ids) {
                findings[[length(findings) + 1L]] <- data.frame(element = xml_name(node), attribute = attribute, value = value, referenced_ids = substring(value, 2L), stringsAsFactors = FALSE)
            }
        }
    }
    if (length(findings) == 0L) {
        return(data.frame(element = character(), attribute = character(), value = character(), referenced_ids = character()))
    }
    do.call(rbind, findings)
}

function(input_raw, ledger, reverse = FALSE) {
    if (nrow(ledger) == 0L) {
        return(input_raw)
    }
    if (reverse) {
        starts <- ledger$post_value_start_byte
        ends <- ledger$post_value_end_byte
        values <- ledger$pre_value
    }
    else {
        starts <- ledger$pre_value_start_byte
        ends <- ledger$pre_value_end_byte
        values <- ledger$post_value
    }
    order_descending <- order(starts, decreasing = TRUE)
    output <- input_raw
    for (i in order_descending) {
        start <- starts[[i]]
        end <- ends[[i]]
        before <- if (start > 1L) 
            output[seq_len(start - 1L)]
        else raw()
        after <- if (end < length(output)) 
            output[seq.int(end + 1L, length(output))]
        else raw()
        output <- c(before, charToRaw(enc2utf8(values[[i]])), after)
    }
    output
}

function(doc) {
    tables <- xml_find_all(doc, ".//table[contains(concat(' ', normalize-space(@class), ' '), ' gt_table ')]")
    for (table in tables) {
        id_nodes <- xml_find_all(table, "self::*[@id] | .//*[@id]")
        header_nodes <- xml_find_all(table, "self::*[@headers] | .//*[@headers]")
        if (length(id_nodes) > 0L) {
            xml_set_attr(id_nodes, "id", "__GT_INTERNAL_ID__")
        }
        if (length(header_nodes) > 0L) {
            xml_set_attr(header_nodes, "headers", "__GT_HEADERS__")
        }
    }
    as.character(doc)
}

function(input_text, output_text, ledger, endpoint_count) {
    input_doc <- read_html(input_text)
    output_doc <- read_html(output_text)
    table_xpath <- paste0(".//table[contains(concat(' ', normalize-space(@class), ' '),", " ' gt_table ')]")
    input_tables <- xml_find_all(input_doc, table_xpath)
    output_tables <- xml_find_all(output_doc, table_xpath)
    stopifnot(length(input_tables) == endpoint_count, length(output_tables) == endpoint_count)
    input_text_values <- vapply(input_tables, xml_text, character(1))
    output_text_values <- vapply(output_tables, xml_text, character(1))
    counts <- function(tables) {
        vapply(tables, function(table) {
            c(rows = length(xml_find_all(table, ".//tr")), cells = length(xml_find_all(table, ".//th | .//td")), header_cells = length(xml_find_all(table, ".//th")), ids = length(xml_find_all(table, "self::*[@id] | .//*[@id]")), headers = length(xml_find_all(table, "self::*[@headers] | .//*[@headers]")))
        }, numeric(5))
    }
    stopifnot(identical(input_text_values, output_text_values), identical(counts(input_tables), counts(output_tables)), identical(xml_text(input_doc), xml_text(output_doc)))
    output_ids <- xml_attr(xml_find_all(output_doc, ".//*[@id]"), "id")
    output_ids <- output_ids[!is.na(output_ids) & nzchar(output_ids)]
    stopifnot(!anyDuplicated(output_ids))
    for (table in output_tables) {
        ids <- xml_attr(xml_find_all(table, "self::*[@id] | .//*[@id]"), "id")
        ids <- ids[!is.na(ids) & nzchar(ids)]
        id_nodes <- xml_find_all(table, "self::*[@id] | .//*[@id]")
        header_values <- xml_attr(xml_find_all(table, "self::*[@headers] | .//*[@headers]"), "headers")
        for (value in header_values) {
            tokens <- strsplit(value, "[[:space:]]+")[[1L]]
            positions <- match(tokens, ids)
            stopifnot(!anyNA(positions), all(vapply(tokens, function(token) sum(ids == token) == 1L, logical(1))), all(xml_name(id_nodes[positions]) == "th"))
        }
    }
    stopifnot(identical(normalized_dom_without_mutable_values(read_html(input_text)), normalized_dom_without_mutable_values(read_html(output_text))))
    header_rows <- ledger$attribute == "headers"
    stopifnot(all(vapply(which(header_rows), function(i) {
        intended <- strsplit(ledger$intended_post_ids[[i]], "\\|", fixed = FALSE)[[1L]]
        rendered <- strsplit(ledger$post_value[[i]], "[[:space:]]+")[[1L]]
        identical(intended, rendered)
    }, logical(1))))
    invisible(TRUE)
}

function(tables) {
    vapply(tables, function(table) {
        c(rows = length(xml_find_all(table, ".//tr")), cells = length(xml_find_all(table, ".//th | .//td")), header_cells = length(xml_find_all(table, ".//th")), ids = length(xml_find_all(table, "self::*[@id] | .//*[@id]")), headers = length(xml_find_all(table, "self::*[@headers] | .//*[@headers]")))
    }, numeric(5))
}

