function(paths, table_outputs, source_outputs, audit_outputs) {
    records <- list()
    write_group <- function(outputs, directory, artifact_type) {
        lapply(names(outputs), function(filename) {
            path <- file.path(directory, filename)
            write_descriptive_csv(outputs[[filename]], path)
            record <- file_artifact_record(path, paths$root, artifact_type = artifact_type, placement = if (grepl("chest", filename)) 
                "chest"
            else if (grepl("near_eye", filename)) 
                "near_eye"
            else "mixed_or_not_applicable")
            record$rows <- nrow(outputs[[filename]])
            record$columns <- ncol(outputs[[filename]])
            record
        })
    }
    records <- c(records, write_group(table_outputs, paths$table_dir, "descriptive_table_csv"), write_group(source_outputs, paths$source_dir, "figure_source_data_csv"), write_group(audit_outputs, paths$audit_dir, "descriptive_audit_csv"))
    dplyr::bind_rows(records)
}

