function(paths, figure_ids = descriptive_figure_spec()$figure_id) {
    spec <- descriptive_figure_spec()
    unknown_figure_ids <- setdiff(figure_ids, spec$figure_id)
    if (length(unknown_figure_ids)) {
        stop("Unknown descriptive figure id: ", paste(unknown_figure_ids, collapse = ", "), call. = FALSE)
    }
    source <- list()
    profile_figure_ids <- c("descriptive_overview", "near_eye_site_profiles", "chest_site_profiles")
