    if ("time_series_to_metrics" %in% figure_ids) {
        source$series <- dplyr::mutate(read_plot_source_csv(file.path(paths$source_dir, "time_series_replica_30_minute.csv")), local_date = as.Date(.data$local_date))
        source$states <- dplyr::mutate(read_plot_source_csv(file.path(paths$source_dir, "time_series_replica_states.csv")), local_date = as.Date(.data$local_date))
        source$time_metrics <- dplyr::mutate(read_plot_source_csv(file.path(paths$source_dir, "time_series_replica_metrics.csv")), local_date = as.Date(.data$local_date))
    }
