        source$bounds <- read_plot_source_csv(file.path(paths$source_dir, "photoperiod_latitude_bounds.csv"))
    }
    plot_builders <- list(descriptive_overview = function() {
        make_overview_replica_figure(file.path(paths$root, "assets", "2026-03-30_MeLiDos_Protocol.png"), source$locations, source$world, source$collection_intervals, source$collection_days, source$profile, source$state, source$period)
    }, near_eye_site_profiles = function() {
        make_site_profile_replica_figure(source$profile, source$state, source$period, "near_eye")
    }, chest_site_profiles = function() {
        make_site_profile_replica_figure(source$profile, source$state, source$period, "chest")
    }, near_eye_metric_distributions = function() {
        make_metric_distributions_replica_figure(source$metric)
    }, time_series_to_metrics = function() {
        make_time_series_replica_figure(source$series, source$states, source$time_metrics)
    }, latitude_photoperiod_diagnostic = function() {
        make_latitude_photoperiod_replica_figure(source$latitude, source$bounds)
    })
    plots <- stats::setNames(lapply(figure_ids, function(figure_id) plot_builders[[figure_id]]()), figure_ids)
    source_map <- descriptive_figure_source_map()
    records <- list()
    for (figure_id in figure_ids) {
        row <- spec[spec$figure_id == figure_id, , drop = FALSE]
        outputs <- save_descriptive_figure(plots[[figure_id]], file.path(paths$figure_dir, figure_id), width = row$base_width_in[[1L]], height = row$base_height_in[[1L]], dpi = row$dpi[[1L]], scale = row$export_scale_multiplier[[1L]])
        mockup_path <- file.path(paths$root, row$a4_mockup_path[[1L]])
        save_descriptive_a4_mockup(figure_png = outputs[["png"]], mockup_png = mockup_path, figure_width_mm = row$print_display_width_mm[[1L]], figure_height_mm = row$print_display_height_mm[[1L]], dpi = row$a4_mockup_dpi[[1L]])
        sources <- file.path("artifacts/11_source_data/descriptives", source_map[[figure_id]])
        for (format in names(outputs)) {
            record <- file_artifact_record(outputs[[format]], paths$root, artifact_type = paste0("descriptive_figure_", format), placement = row$placement[[1L]], source_data = paste(sources, collapse = ";"))
            record$rows <- NA_integer_
            record$columns <- NA_integer_
            record$figure_id <- figure_id
            record$width_in <- row$export_width_in[[1L]]
            record$height_in <- row$export_height_in[[1L]]
            record$dpi <- if (format %in% c("png", "jpeg", "pdf")) 
                row$dpi[[1L]]
            else NA_integer_
            records[[length(records) + 1L]] <- record
        }
        mockup_record <- file_artifact_record(mockup_path, paths$root, artifact_type = "descriptive_figure_a4_mockup", placement = row$placement[[1L]], source_data = relative_descriptive_path(outputs[["png"]], paths$root))
        mockup_record$rows <- NA_integer_
        mockup_record$columns <- NA_integer_
        mockup_record$figure_id <- figure_id
        mockup_record$width_in <- 210/25.4
        mockup_record$height_in <- 297/25.4
        mockup_record$dpi <- row$a4_mockup_dpi[[1L]]
        records[[length(records) + 1L]] <- mockup_record
    }
    qa <- build_descriptive_figure_qa(spec, paths)
    list(plots = plots, records = dplyr::bind_rows(records), spec = spec, qa = qa)
}

