function(metric_registry = h01_metric_registry()) {
    required <- c("metric_order", "metric_id", "analysis_unit", "response_family", "response_transform", "effect_scale", "lower_bound", "upper_bound", "audit_upper_threshold")
    missing <- setdiff(required, names(metric_registry))
    if (length(missing) > 0L) {
        h01_abort("H01 metric registry is missing column(s): %s", paste(missing, collapse = ", "))
    }
    if (nrow(metric_registry) != 17L || !identical(metric_registry$metric_order, seq_len(17L)) || anyDuplicated(metric_registry$metric_id)) {
        h01_abort("H01 metric registry must contain 17 ordered, unique metrics")
    }
    if (!all(metric_registry$analysis_unit %in% c("participant", "participant_day")) || !all(metric_registry$response_family %in% c("gaussian", "tweedie_log"))) {
        h01_abort("H01 metric registry contains an unsupported model contract")
    }
    allowed_transforms <- c("logit", "identity", "log10_offset_0.1", "clock_hours", "clock_hours_midnight_after_16")
    if (!all(metric_registry$response_transform %in% allowed_transforms)) {
        h01_abort("H01 metric registry contains an unsupported transformation")
    }
    finite_audit_threshold <- is.finite(metric_registry$audit_upper_threshold)
    if (any(finite_audit_threshold & metric_registry$audit_upper_threshold <= metric_registry$lower_bound) || any(finite_audit_threshold & is.finite(metric_registry$upper_bound) & metric_registry$audit_upper_threshold > metric_registry$upper_bound)) {
        h01_abort("H01 audit thresholds must lie inside the response bounds")
    }
    invisible(metric_registry)
}

function(analysis_unit, fixed_terms, response = "response_value") {
    if (!analysis_unit %in% c("participant", "participant_day")) {
        h01_abort("Unknown H01 analysis unit: %s", analysis_unit)
    }
    rhs <- if (length(fixed_terms) == 0L) {
        "1"
    }
    else {
        paste(fixed_terms, collapse = " + ")
    }
    if (analysis_unit == "participant_day") {
        rhs <- paste(rhs, "+ (1 | participant_key)")
    }
    stats::as.formula(paste(response, "~", rhs))
}

function(analysis_unit, preregistered_scope = FALSE) {
    include_photoperiod <- !preregistered_scope
    site_terms <- if (include_photoperiod) {
        c("site", "photoperiod_centered_hours")
    }
    else {
        "site"
    }
    latitude_terms <- if (include_photoperiod) {
        c("absolute_latitude_10deg_centered", "photoperiod_centered_hours")
    }
    else {
        "absolute_latitude_10deg_centered"
    }
    no_site_terms <- if (include_photoperiod) {
        "photoperiod_centered_hours"
    }
    else {
        character()
    }
    list(site_full = h01_model_formula(analysis_unit, site_terms), no_site = h01_model_formula(analysis_unit, no_site_terms), no_photoperiod = h01_model_formula(analysis_unit, "site"), latitude_full = h01_model_formula(analysis_unit, latitude_terms), no_latitude = h01_model_formula(analysis_unit, no_site_terms), random_site = if (analysis_unit == "participant_day") {
        if (include_photoperiod) {
            stats::as.formula(paste0("response_value ~ photoperiod_centered_hours + ", "(1 | site) + (1 | participant_key)"))
        } else {
            stats::as.formula("response_value ~ 1 + (1 | site) + (1 | participant_key)")
        }
    } else {
        if (include_photoperiod) {
            stats::as.formula("response_value ~ photoperiod_centered_hours + (1 | site)")
        } else {
            stats::as.formula("response_value ~ 1 + (1 | site)")
        }
    })
}

