function(value) {
    if (!is.numeric(value)) {
        stop("P-values must be supplied as a numeric vector.", call. = FALSE)
    }
    invalid <- !is.na(value) & (!is.finite(value) | value < 0 | value > 1)
    if (any(invalid)) {
        stop("Finite p-values must lie between 0 and 1 inclusive.", call. = FALSE)
    }
    invisible(value)
}

function(value, significant, na_label = "—") {
    nh_validate_p_values(value)
    if (!is.logical(significant)) {
        stop("The significance indicator must be logical.", call. = FALSE)
    }
    if (length(significant) == 1L && length(value) != 1L) {
        significant <- rep.int(significant, length(value))
    }
    if (length(significant) != length(value)) {
        stop("The significance indicator must have length one or match the p-values.", call. = FALSE)
    }
    data.frame(p_value = value, p_display = nh_format_p_value(value, na_label = na_label), p_bold = !is.na(value) & !is.na(significant) & significant, stringsAsFactors = FALSE)
}

function(start = getwd()) {
    override <- Sys.getenv("NATHEALTH_PROJECT_ROOT", unset = "")
    if (nzchar(override)) {
        root <- normalizePath(override, winslash = "/", mustWork = TRUE)
    }
    else {
        root <- normalizePath(start, winslash = "/", mustWork = TRUE)
        repeat {
            markers <- file.exists(file.path(root, c("_quarto.yml", "renv.lock")))
            if (all(markers)) {
                break
            }
            parent <- dirname(root)
            if (identical(parent, root)) {
                stop("Could not locate project root from ", start, call. = FALSE)
            }
            root <- parent
        }
    }
    root
}

