function(path) {
    if (!file.exists(path)) {
        stop("Cannot hash missing artifact: ", path, call. = FALSE)
    }
    connection <- file(path, open = "rb")
    on.exit(close(connection), add = TRUE)
    unname(unclass(as.character(openssl::sha256(connection))))
}

function(temporary, path) {
    if (!file.exists(temporary)) {
        stop("Cannot install missing temporary artifact: ", temporary, call. = FALSE)
    }
    if (!file.rename(temporary, path)) {
        stop("Failed to atomically install artifact: ", path, call. = FALSE)
    }
    invisible(path)
}

function(path, expected_class = NULL) {
    if (!file.exists(path)) {
        stop("Required RDS artifact does not exist: ", path, call. = FALSE)
    }
    object <- readRDS(path)
    if (!is.null(expected_class) && !inherits(object, expected_class)) {
        stop("Artifact ", path, " has class ", paste(class(object), collapse = "/"), "; expected ", expected_class, call. = FALSE)
    }
    object
}

function(data, path, producer, metadata = list()) {
    if (!is.data.frame(data)) {
        stop("CSV artifacts must be data frames", call. = FALSE)
    }
    dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
    temporary <- tempfile(pattern = paste0(basename(path), "."), tmpdir = dirname(path))
    on.exit(unlink(temporary), add = TRUE)
    readr::write_csv(data, temporary, na = "")
    atomic_replace_artifact(temporary, path)
    info <- file.info(path)
    c(list(path = normalizePath(path, winslash = "/", mustWork = TRUE), sha256 = artifact_sha256(path), bytes = unname(info$size), rows = nrow(data), columns = ncol(data), producer = producer, r_version = as.character(getRversion()), written_utc = format(Sys.time(), tz = "UTC", usetz = TRUE)), metadata)
}

