function(root, input = h02_input_contract(root)) {
    observed <- vapply(input$path, artifact_sha256, character(1))
    mismatch <- observed != input$sha256
    if (any(mismatch)) {
        rows <- which(mismatch)
        h02_abort("H02 input hash mismatch: %s", paste(sprintf("%s expected %s observed %s", input$input_id[rows], input$sha256[rows], observed[rows]), collapse = "; "))
    }
    path_for <- function(id) input$path[match(id, input$input_id)]
    hash_for <- function(id) input$sha256[match(id, input$input_id)]
    base_manifest <- readr::read_csv(path_for("base_model_data_manifest"), show_col_types = FALSE)
    base_expected <- dplyr::mutate(tibble::tribble(~artifact_id, ~input_id, "glasses_30_minute_context", "main_glasses", "chest_30_minute_context", "main_chest"), expected_sha256 = vapply(.data$input_id, hash_for, character(1)))
    base_observed <- dplyr::right_join(dplyr::select(dplyr::filter(base_manifest, .data$artifact_id %in% base_expected$artifact_id), "artifact_id", observed_sha256 = "sha256", "status"), base_expected, by = "artifact_id", relationship = "one-to-one")
    if (anyNA(base_observed$observed_sha256) || any(base_observed$status != "PASS") || any(base_observed$observed_sha256 != base_observed$expected_sha256)) {
        h02_abort("The approved base-data manifest does not verify both H02 inputs")
    }
    temporal_manifest <- readr::read_csv(path_for("temporal_provenance_manifest"), show_col_types = FALSE)
    temporal_expected <- dplyr::mutate(tibble::tribble(~artifact_type, ~input_id, "wall_outcome_links_rds", "wall_outcome_links", "true_utc_source_bins_rds", "true_utc_source_bins"), expected_sha256 = vapply(.data$input_id, hash_for, character(1)))
    temporal_observed <- dplyr::right_join(dplyr::select(dplyr::filter(temporal_manifest, .data$artifact_type %in% temporal_expected$artifact_type), "artifact_type", observed_sha256 = "sha256", "status"), temporal_expected, by = "artifact_type", relationship = "one-to-one")
    if (anyNA(temporal_observed$observed_sha256) || any(temporal_observed$status != "PASS") || any(temporal_observed$observed_sha256 != temporal_observed$expected_sha256)) {
        h02_abort("The approved temporal manifest does not verify both H02 inputs")
    }
    dplyr::mutate(input, observed_sha256 = observed, hash_verified = TRUE)
}

