function(root) {
    expected <- descriptive_expected_manifests(root)
    expected$available <- file.exists(expected$path)
    expected$observed_sha256 <- vapply(expected$path, function(path) {
        if (!file.exists(path)) 
            return(NA_character_)
        artifact_sha256(path)
    }, character(1))
    expected$status <- ifelse(!expected$available, "MISSING", ifelse(expected$observed_sha256 == expected$expected_sha256, "PASS", "HASH_MISMATCH"))
    if (!all(expected$status == "PASS")) {
        request <- write_descriptive_change_request(root, expected, "At least one required shared manifest is missing or has changed.")
        stop("Shared manifest verification failed. See ", request, call. = FALSE)
    }
    normalized_root <- normalizePath(root, winslash = "/", mustWork = TRUE)
    root_prefix <- paste0(normalized_root, "/")
    expected$path <- vapply(expected$path, function(path) {
        normalized_path <- normalizePath(path, winslash = "/", mustWork = FALSE)
        if (startsWith(normalized_path, root_prefix)) {
            substring(normalized_path, nchar(root_prefix) + 1L)
        }
        else {
            normalized_path
        }
    }, character(1))
    expected
}

function(manifest, root) {
    if (!"path" %in% names(manifest)) {
        stop("Shared artifact manifest has no `path` column", call. = FALSE)
    }
    paths <- as.character(manifest$path)
    absolute <- grepl("^/", paths)
    paths[!absolute] <- file.path(root, paths[!absolute])
    vapply(paths, normalizePath, character(1), winslash = "/", mustWork = FALSE)
}

function(root) {
    specs <- descriptive_input_spec(root)
    manifests <- descriptive_expected_manifests(root)
    specs$expected_sha256 <- NA_character_
    specs$observed_sha256 <- NA_character_
    specs$status <- "NOT_CHECKED"
    for (i in seq_len(nrow(specs))) {
        manifest_path <- manifests$path[match(specs$manifest_id[[i]], manifests$manifest_id)]
        if (!file.exists(specs$path[[i]])) {
            specs$status[[i]] <- "MISSING"
            next
        }
        manifest <- utils::read.csv(manifest_path, stringsAsFactors = FALSE, check.names = FALSE, na.strings = character())
        indexed_paths <- manifest_artifact_paths(manifest, root)
        target <- normalizePath(specs$path[[i]], winslash = "/", mustWork = FALSE)
        index <- match(target, indexed_paths)
        if (is.na(index) || !"sha256" %in% names(manifest)) {
            specs$status[[i]] <- "NOT_IN_MANIFEST"
            next
        }
        specs$expected_sha256[[i]] <- manifest$sha256[[index]]
        specs$observed_sha256[[i]] <- artifact_sha256(specs$path[[i]])
        specs$status[[i]] <- if (identical(specs$expected_sha256[[i]], specs$observed_sha256[[i]])) 
            "PASS"
        else "HASH_MISMATCH"
    }
    if (!all(specs$status == "PASS")) {
        stop("Prepared descriptive input verification failed for: ", paste(specs$input_id[specs$status != "PASS"], collapse = ", "), call. = FALSE)
    }
    normalized_root <- normalizePath(root, winslash = "/", mustWork = TRUE)
    root_prefix <- paste0(normalized_root, "/")
    specs$path <- vapply(specs$path, function(path) {
        normalized_path <- normalizePath(path, winslash = "/", mustWork = FALSE)
        if (startsWith(normalized_path, root_prefix)) {
            substring(normalized_path, nchar(root_prefix) + 1L)
        }
        else {
            normalized_path
        }
    }, character(1))
    specs
}

function(data, key, label) {
    if (!all(key %in% names(data))) {
        stop(label, " is missing key columns", call. = FALSE)
    }
    duplicated_key <- duplicated(data[key])
    if (any(duplicated_key)) {
        stop(label, " has duplicate key rows", call. = FALSE)
    }
    invisible(data)
}

function(x) {
    x <- x[is.finite(x)]
    if (length(x) == 0L) 
        NA_real_
    else stats::median(x)
}

function(x) {
    x <- x[is.finite(x)]
    if (length(x) == 0L) 
        NA_real_
    else mean(x)
}

function(x) {
    x <- x[is.finite(x)]
    if (length(x) < 2L) 
        NA_real_
    else stats::sd(x)
}

function(x, probability) {
    x <- x[is.finite(x)]
    if (length(x) == 0L) 
        return(NA_real_)
    unname(stats::quantile(x, probability, names = FALSE, type = 7L))
}

function(x, confidence = 0.95) {
    x <- sort(x[is.finite(x)])
    n <- length(x)
    if (n == 0L) {
        return(c(lower = NA_real_, upper = NA_real_))
    }
    alpha <- 1 - confidence
    rank_lower <- max(1L, as.integer(stats::qbinom(alpha/2, n, 0.5)))
    rank_upper <- min(n, n - rank_lower + 1L)
    c(lower = x[[rank_lower]], upper = x[[rank_upper]])
}

function(minutes, period = 1440) {
    minutes <- minutes[is.finite(minutes)]%%period
    n <- length(minutes)
    if (n == 0L) {
        return(c(mean = NA_real_, q1 = NA_real_, median = NA_real_, q3 = NA_real_, resultant = NA_real_))
    }
    radians <- minutes/period * 2 * pi
    vector <- mean(exp((0+1i) * radians))
    resultant <- Mod(vector)
    center <- if (resultant >= 0.1) {
        (Arg(vector)%%(2 * pi))/(2 * pi) * period
    }
    else {
        NA_real_
    }
    if (!is.finite(center)) {
        return(c(mean = NA_real_, q1 = NA_real_, median = NA_real_, q3 = NA_real_, resultant = resultant))
    }
    difference <- (minutes - center + period/2)%%period - period/2
    quantiles <- stats::quantile(difference, probs = c(0.25, 0.5, 0.75), names = FALSE, type = 7L)
    c(mean = center, q1 = (center + quantiles[[1L]])%%period, median = (center + quantiles[[2L]])%%period, q3 = (center + quantiles[[3L]])%%period, resultant = resultant)
}

function(resultant, period = 1440) {
    if (!is.finite(resultant) || resultant <= 0 || resultant > 1) {
        return(NA_real_)
    }
    sqrt(-2 * log(resultant)) * period/(2 * pi)
}

function(x) {
    ifelse(is.finite(x), sprintf("%02d:%02d", (round(x)%/%60L)%%24L, round(x)%%60L), "Not estimable")
}

function(x, digits = 2L) {
    ifelse(is.finite(x), trimws(formatC(x, format = "fg", digits = digits, big.mark = ",")), "Not estimable")
}

function(start = getwd()) {
    current <- normalizePath(start, winslash = "/", mustWork = TRUE)
    repeat {
        candidate <- file.path(current, "config", "site_display_registry.csv")
        if (file.exists(candidate)) 
            return(candidate)
        parent <- dirname(current)
        if (identical(parent, current)) {
            stop("Could not locate config/site_display_registry.csv", call. = FALSE)
        }
        current <- parent
    }
}

function(root = NULL) {
    path <- if (is.null(root)) {
        locate_site_display_registry()
    }
    else {
        file.path(root, "config", "site_display_registry.csv")
    }
    if (!file.exists(path)) {
        stop("Shared site display registry is unavailable: ", path, call. = FALSE)
    }
    registry <- utils::read.csv(path, stringsAsFactors = FALSE, check.names = FALSE, na.strings = character(), fileEncoding = "UTF-8")
    required <- c("site", "display_order", "display_name", "color_hex")
    if (!identical(names(registry), required)) {
        stop("Site display registry columns must be exactly: ", paste(required, collapse = ", "), call. = FALSE)
    }
    registry$display_order <- as.integer(registry$display_order)
    if (!nrow(registry) || anyNA(registry) || anyDuplicated(registry$site) || anyDuplicated(registry$display_order) || anyDuplicated(registry$display_name) || !identical(sort(registry$display_order), seq_len(nrow(registry))) || any(!grepl("^#[[:xdigit:]]{6}$", registry$color_hex))) {
        stop("Shared site display registry failed validation", call. = FALSE)
    }
    registry <- registry[order(registry$display_order), , drop = FALSE]
    rownames(registry) <- NULL
    .descriptive_site_display_cache$registry <- registry
    .descriptive_site_display_cache$path <- normalizePath(path, winslash = "/", mustWork = TRUE)
    invisible(registry)
}

function() {
    if (!exists("registry", envir = .descriptive_site_display_cache, inherits = FALSE)) {
        configure_descriptive_site_display()
    }
    .descriptive_site_display_cache$registry
}

function() {
