    stats::setNames(registry$display_name, registry$site)
}

function(root) {
    registry <- configure_descriptive_site_display(root)
    path <- .descriptive_site_display_cache$path
    normalized_root <- normalizePath(root, winslash = "/", mustWork = TRUE)
    prefix <- paste0(normalized_root, "/")
    relative_path <- if (startsWith(path, prefix)) {
        substring(path, nchar(prefix) + 1L)
    }
    else {
        path
    }
    dplyr::mutate(registry, decision_id = "DISPLAY-001", registry_path = relative_path, registry_sha256 = artifact_sha256(path), .before = 1L)
}

function(colour, fraction) {
    fraction <- pmax(0, pmin(1, fraction))
    if (length(colour) == 1L) {
        colour <- rep(colour, length(fraction))
    }
    if (length(colour) != length(fraction)) {
        stop("Colour and fraction lengths differ", call. = FALSE)
    }
    mapply(function(single_colour, weight) {
        rgb <- grDevices::col2rgb(single_colour)/255
        mixed <- rgb * weight + (1 - weight)
        grDevices::rgb(mixed[[1L]], mixed[[2L]], mixed[[3L]])
    }, colour, fraction, USE.NAMES = FALSE)
}

function(data, path) {
    if (!is.data.frame(data)) {
        stop("Descriptive CSV output must be a data frame", call. = FALSE)
    }
    dir.create(dirname(path), recursive = TRUE, showWarnings = FALSE)
    readr::write_csv(data, path, na = "")
    invisible(path)
}

function(png_path, pdf_path, width, height) {
    raster <- png::readPNG(png_path, native = TRUE)
    grDevices::pdf(file = pdf_path, width = width, height = height, onefile = FALSE, paper = "special", bg = "white", colormodel = "srgb", useDingbats = FALSE, compress = TRUE, timestamp = FALSE)
    device_id <- grDevices::dev.cur()
    on.exit({
        if (device_id %in% grDevices::dev.list()) {
            grDevices::dev.off(device_id)
        }
    }, add = TRUE)
    grid::grid.newpage()
    grid::grid.raster(raster, x = 0.5, y = 0.5, width = grid::unit(1, "npc"), height = grid::unit(1, "npc"), interpolate = FALSE)
    grDevices::dev.off(device_id)
    invisible(pdf_path)
}

function(figure_png, mockup_png, figure_width_mm, figure_height_mm, dpi = 150) {
    if (figure_width_mm > 170 || figure_height_mm > 257) {
        stop("The figure does not fit the 20-mm A4 content area", call. = FALSE)
    }
    dir.create(dirname(mockup_png), recursive = TRUE, showWarnings = FALSE)
    raster <- png::readPNG(figure_png, native = TRUE)
    a4_width_px <- as.integer(round(210/25.4 * dpi))
    a4_height_px <- as.integer(round(297/25.4 * dpi))
    ragg::agg_png(filename = mockup_png, width = a4_width_px, height = a4_height_px, units = "px", res = dpi, background = "white")
    device_id <- grDevices::dev.cur()
    on.exit({
        if (device_id %in% grDevices::dev.list()) grDevices::dev.off(device_id)
    }, add = TRUE)
    grid::grid.newpage()
    grid::grid.raster(raster, x = grid::unit(105, "mm"), y = grid::unit(297 - 20 - figure_height_mm/2, "mm"), width = grid::unit(figure_width_mm, "mm"), height = grid::unit(figure_height_mm, "mm"), interpolate = FALSE)
    grDevices::dev.off(device_id)
    invisible(mockup_png)
}

function(path, root, artifact_type, placement = "not_applicable", source_data = "") {
