    relative <- substring(normalizePath(path, winslash = "/", mustWork = TRUE), nchar(normalizePath(root, winslash = "/", mustWork = TRUE)) + 2L)
    data.frame(artifact_type = artifact_type, placement = placement, path = relative, sha256 = artifact_sha256(path), bytes = unname(info$size), source_data = source_data, producer = "scripts/descriptives/build_descriptives.R", r_version = as.character(getRversion()), stringsAsFactors = FALSE)
}

