function(inputs) {
    day_key <- c("site", "Id", "local_date")
    assert_unique_descriptive_key(inputs$participant_day$near_eye, day_key, "Near-eye participant-day metrics")
    assert_unique_descriptive_key(inputs$participant_day$chest, day_key, "Chest participant-day metrics")
    if (nrow(inputs$participant_day$near_eye) != 816L) {
        stop("Expected 816 near-eye participant-days", call. = FALSE)
    }
    if (nrow(inputs$participant_day$chest) != 902L) {
        stop("Expected 902 chest participant-days", call. = FALSE)
    }
    if (dplyr::n_distinct(inputs$participant_day$near_eye$Id) != 141L) {
        stop("Expected 141 near-eye participants", call. = FALSE)
    }
    if (dplyr::n_distinct(inputs$participant_day$chest$Id) != 154L) {
        stop("Expected 154 chest participants", call. = FALSE)
    }
    gap_mder <- prepare_gap_mder_values(inputs)
    gap_mder_summary <- dplyr::arrange(dplyr::summarise(dplyr::group_by(gap_mder, .data$placement), total_days = dplyr::n(), participants = dplyr::n_distinct(.data$Id[.data$finite]), participant_days = sum(.data$finite), mean = mean(.data$value[.data$finite]), median = stats::median(.data$value[.data$finite]), .groups = "drop"), match(.data$placement, c("near_eye", "chest")))
    if (!identical(gap_mder_summary$total_days, c(811L, 897L)) || !identical(gap_mder_summary$participants, c(137L, 152L)) || !identical(gap_mder_summary$participant_days, c(687L, 723L)) || max(abs(gap_mder_summary$mean - c(0.7242573, 0.7567377))) > 5e-08 || max(abs(gap_mder_summary$median - c(0.7238676, 0.7495175))) > 5e-08) {
        stop("The repaired gap MDER summary differs from METRIC-010", call. = FALSE)
    }
    paired <- dplyr::inner_join(dplyr::select(inputs$participant_day$near_eye, dplyr::all_of(day_key)), dplyr::select(inputs$participant_day$chest, dplyr::all_of(day_key)), by = day_key)
    if (nrow(paired) != 643L || dplyr::n_distinct(paired$Id) != 112L) {
        stop("Expected 643 paired days from 112 participants", call. = FALSE)
    }
    expected_rows <- c(near_eye = 816L, chest = 902L)
    for (placement in names(expected_rows)) {
        if (nrow(inputs$metrics_30[[placement]]) != expected_rows[[placement]] * 48L) {
            stop("The 30-minute metric grid is incomplete for ", placement, call. = FALSE)
        }
        if (nrow(inputs$metrics_hour[[placement]]) != expected_rows[[placement]] * 24L) {
            stop("The hourly metric grid is incomplete for ", placement, call. = FALSE)
        }
        coverage_keys <- dplyr::distinct(dplyr::filter(inputs$coverage[[placement]], .data$day_eligible), site, Id, local_date)
        metric_keys <- dplyr::distinct(inputs$participant_day[[placement]], site, Id, local_date)
        coverage_key_text <- do.call(paste, c(coverage_keys, list(sep = "\r")))
        metric_key_text <- do.call(paste, c(metric_keys, list(sep = "\r")))
        if (!setequal(coverage_key_text, metric_key_text)) {
            stop("Coverage and metric day keys differ for ", placement, call. = FALSE)
        }
        values <- inputs$coverage[[placement]]$MEDI_eligible
        if (any(values > 1e+05, na.rm = TRUE)) {
            stop("An eligible melEDI value exceeds 100,000 lx", call. = FALSE)
        }
    }
    all_zero_counts <- vapply(inputs$daily_coverage, function(data) sum(data$day_all_zero_medi_excluded, na.rm = TRUE), integer(1))
    if (!identical(unname(all_zero_counts), c(2L, 3L))) {
        stop("Expected two near-eye and three chest all-zero exclusions", call. = FALSE)
    }
    assert_unique_descriptive_key(inputs$solar, c("site", "local_date"), "Site solar context")
    required_bound_columns <- c("absolute_latitude_deg", "minimum_possible_photoperiod_hours", "maximum_possible_photoperiod_hours", "calendar_year", "solar_depression_deg")
    if (!all(required_bound_columns %in% names(inputs$photoperiod_bounds))) {
        stop("The verified H1 photoperiod-bound source is incomplete", call. = FALSE)
    }
    if (any(inputs$photoperiod_bounds$minimum_possible_photoperiod_hours > inputs$photoperiod_bounds$maximum_possible_photoperiod_hours, na.rm = TRUE)) {
        stop("The verified H1 photoperiod bounds are internally inconsistent", call. = FALSE)
    }
    invisible(inputs)
}

