function(data, variable, characteristic, section, analysis_unit = "participant") {
    values <- as.character(data[[variable]])
    available <- !is.na(values) & nzchar(values)
    counts <- as.data.frame(table(values[available]), stringsAsFactors = FALSE)
    names(counts) <- c("level", "count")
    denominator <- sum(available)
    if (nrow(counts) == 0L) {
        counts <- data.frame(level = "No available values", count = 0L)
    }
    counts$percent <- if (denominator > 0) {
        100 * counts$count/denominator
    }
    else {
        NA_real_
    }
    counts$display <- if (denominator > 0) {
        sprintf("%d (%.1f%%)", counts$count, counts$percent)
    }
    else {
        "Not available"
    }
    dplyr::select(dplyr::mutate(counts, section = section, characteristic = characteristic, analysis_unit = analysis_unit, unit = "n (%)", n_available = denominator, n_denominator = denominator, mean = NA_real_, q1 = NA_real_, median = NA_real_, q3 = NA_real_, minimum = NA_real_, maximum = NA_real_, circular_resultant = NA_real_, display = .data$display), section, characteristic, level, analysis_unit, unit, n_available, n_denominator, count, percent, mean, q1, median, q3, minimum, maximum, circular_resultant, 
        display)
}

