function(data, group_key) {
    finite <- data$finite & is.finite(data$value)
    values <- data$value[finite]
    circular <- identical(group_key$display_unit[[1L]], "clock time")
    if (circular) {
        stats <- circular_descriptive_summary(values)
        stats <- c(stats, sd = circular_standard_deviation(stats[["resultant"]]))
        display_mean <- format_clock_minute(stats[["mean"]])
        display_middle <- paste0(format_clock_minute(stats[["median"]]), " [", format_clock_minute(stats[["q1"]]), ", ", format_clock_minute(stats[["q3"]]), "]")
    }
    else {
        stats <- c(mean = finite_mean(values), sd = finite_sd(values), q1 = finite_quantile(values, 0.25), median = finite_median(values), q3 = finite_quantile(values, 0.75), resultant = NA_real_)
        display_mean <- format_number_compact(stats[["mean"]], 4L)
        display_middle <- paste0(format_number_compact(stats[["median"]], 4L), " [", format_number_compact(stats[["q1"]], 4L), ", ", format_number_compact(stats[["q3"]], 4L), "]")
    }
    analysis_unit <- group_key$analysis_unit[[1L]]
    participant_days <- if (identical(analysis_unit, "participant")) {
        sum(data$underlying_days[finite], na.rm = TRUE)
    }
    else {
        dplyr::n_distinct(paste(group_key$site[[1L]], data$Id[finite], data$local_date[finite], sep = "|"))
    }
    data.frame(n_possible_observations = nrow(data), n_observations = sum(finite), n_participants = dplyr::n_distinct(data$Id[finite]), n_participant_days = participant_days, mean = stats[["mean"]], sd = stats[["sd"]], q1 = stats[["q1"]], median = stats[["median"]], q3 = stats[["q3"]], circular_resultant = stats[["resultant"]], mean_display = display_mean, median_middle_50_display = display_middle, stringsAsFactors = FALSE)
}

