function(minutes) {
    ifelse(is.finite(minutes), sprintf("%02d:%02d", round(minutes)%/%60L, round(minutes)%%60L), "Not available")
}

function(hours) {
    format_duration_minutes(60 * hours)
}

function(minutes, max_units = Inf) {
    if (!is.finite(minutes)) 
        return("Not available")
    total <- round(minutes)
    weeks <- total%/%(7L * 1440L)
    total <- total%%(7L * 1440L)
    days <- total%/%1440L
    total <- total%%1440L
    hours <- total%/%60L
    mins <- total%%60L
    parts <- c(if (weeks > 0L) paste0(weeks, "w") else character(), if (days > 0L) paste0(days, "d") else character(), if (hours > 0L) paste0(hours, "h") else character(), if (mins > 0L || !length(c(weeks, days, hours)[c(weeks, days, hours) > 0L])) {
        paste0(mins, " min")
    } else character())
    paste(utils::head(parts, max_units), collapse = " ")
}

function(x) {
    date <- if (is.numeric(x)) 
        as.Date(x, origin = "1970-01-01")
    else as.Date(x)
    ifelse(is.na(date), "Not available", format(date, "%y/%m/%d"))
}

function(x, probs = c(0.05, 0.5, 0.95)) {
    x <- x[is.finite(x)]
    if (!length(x)) 
        return(c(lower = NA_real_, median = NA_real_, upper = NA_real_, n = 0))
    values <- stats::quantile(x, probs = probs, names = FALSE, type = 7L)
    c(lower = values[[1L]], median = values[[2L]], upper = values[[3L]], n = length(x))
}

function(minutes, probs = c(0.05, 0.5, 0.95)) {
    minutes <- minutes[is.finite(minutes)]%%1440
    if (!length(minutes)) {
        return(c(lower = NA_real_, median = NA_real_, upper = NA_real_, n = 0))
    }
    angle <- 2 * pi * minutes/1440
    center <- (atan2(mean(sin(angle)), mean(cos(angle)))%%(2 * pi)) * 1440/(2 * pi)
    displacement <- (minutes - center + 720)%%1440 - 720
    values <- stats::quantile(displacement, probs = probs, names = FALSE, type = 7L)
    c(lower = (center + values[[1L]])%%1440, median = (center + values[[2L]])%%1440, upper = (center + values[[3L]])%%1440, n = length(minutes))
}

