function(value, decimal_places = 3L) {
    if (!is.finite(value)) 
        return("Not estimable")
    if (abs(value) < 0.5 * 10^(-decimal_places)) 
        value <- 0
    formatted <- formatC(value, format = "f", digits = decimal_places, big.mark = ",", decimal.mark = ".")
    sub("\\.?0+$", "", formatted)
}

function(value, metric_id) {
    if (!is.finite(value)) 
        return("Not estimable")
    if (grepl("duration|longest_bout", metric_id)) 
        return(format_duration_hours(value))
    if (grepl("timing|midpoint", metric_id)) 
        return(format_clock_minute(value))
    if (metric_id == "dose_time_sensitive_corrected_medi") {
        return(format_replica_metric_decimal(value/1000, 3L))
    }
    format_replica_metric_decimal(value, 3L)
}

function(value, metric_id) {
    if (!is.finite(value)) 
        return("Not estimable")
    if (grepl("duration|longest_bout", metric_id)) {
        return(format_duration_hours(value))
    }
    if (grepl("timing|midpoint", metric_id)) {
        return(format_duration_minutes(value))
    }
    if (metric_id == "dose_time_sensitive_corrected_medi") {
        return(format_replica_metric_decimal(value/1000, 3L))
    }
    format_replica_metric_decimal(value, 3L)
}

