function(root) {
    contract <- gap_timing_unaware_near_eye_contract(root)
    if (!file.exists(contract$path[[1L]])) {
        stop("Gap-timing-unaware near-eye source is missing", call. = FALSE)
    }
    observed_sha256 <- artifact_sha256(contract$path[[1L]])
    if (!identical(observed_sha256, contract$expected_sha256[[1L]])) {
        stop("Gap-timing-unaware near-eye source hash changed: ", observed_sha256, call. = FALSE)
    }
    workspace <- new.env(parent = baseenv())
    loaded_objects <- base::load(contract$path[[1L]], envir = workspace)
    if (!contract$object[[1L]] %in% loaded_objects) {
        stop("Expected gap-timing-unaware object is absent", call. = FALSE)
    }
    data <- dplyr::as_tibble(dplyr::ungroup(workspace[[contract$object[[1L]]]]))
    required <- c("site", "Id", "Date", "Datetime", "MEDI", "photoperiod.state")
    if (!all(required %in% names(data))) {
        stop("Gap-timing-unaware near-eye object is incomplete", call. = FALSE)
    }
    list(data = data, provenance = dplyr::transmute(contract, dataset_id = .data$dataset_id, reader_label = .data$reader_label, source_path = substring(normalizePath(.data$path, winslash = "/", mustWork = TRUE), nchar(normalizePath(root, winslash = "/", mustWork = TRUE)) + 2L), source_object = .data$object, source_sha256 = observed_sha256, aggregation = .data$aggregation))
}

