    selected_keys <- dplyr::select(selected, site, Id, Date, weekday, participant_order, protocol_day)
    series <- dplyr::arrange(dplyr::transmute(dplyr::mutate(dplyr::left_join(selected_samples, dplyr::select(selected_keys, "site", "Id", "Date", "participant_order", "protocol_day", "weekday"), by = c("site", "Id", "Date", "protocol_day", "weekday")), clock_bin = lubridate::hour(.data$Datetime) * 60 + lubridate::minute(.data$Datetime), aligned_minute = (.data$protocol_day - 1L) * 1440 + .data$clock_bin), site = .data$site, participant = .data$Id, participant_order = .data$participant_order, local_date = as.Date(.data$Date), 
        weekday = .data$weekday, protocol_day = .data$protocol_day, clock_bin = .data$clock_bin, aligned_minute = .data$aligned_minute, melEDI_lx = .data$MEDI, sample_available = is.finite(.data$MEDI), photoperiod_state = .data$photoperiod.state, daytime = .data$photoperiod.state == "day", aggregation_method = "Stored floor-aligned 30-minute arithmetic mean", dataset = "Gap-timing-unaware near-eye dataset", analysis_unit = "participant-30-minute"), .data$participant_order, .data$aligned_minute)
    daily_solar_context <- dplyr::mutate(dplyr::summarise(dplyr::group_by(dplyr::left_join(selected_samples, dplyr::select(selected_keys, "site", "Id", "Date", "participant_order", "protocol_day", "weekday"), by = c("site", "Id", "Date", "protocol_day", "weekday")), .data$site, .data$Id, .data$Date, .data$participant_order, .data$protocol_day, .data$weekday), dawn = mean(.data$dawn, na.rm = TRUE), dusk = mean(.data$dusk, na.rm = TRUE), .groups = "drop"), day_start = (.data$protocol_day - 1L) * 1440, 
