function(characteristic, site, previous) {
    if (is.na(previous)) {
        return(paste("This characteristic was absent from the displayed earlier table and is", "now added with an explicit updated-data denominator."))
    }
    if (characteristic %in% c("Institution", "Country", "City", "Coordinates")) {
        if (characteristic == "Institution" && site %in% c("MPI", "TUM")) {
            return(paste("The earlier table interchanged the MPI and TUM institution labels.", "The updated cell follows the verified site metadata."))
        }
        return(paste("The table structure is retained; the updated cell is tied to the", "verified site and solar-context metadata."))
    }
    if (characteristic == "Participants") {
        return(paste("The earlier cell mixed the full roster and two placement-specific", "counts. The updated cell keeps the roster, near-eye, chest, and paired", "counts distinct across every available non-all-zero day."))
    }
    if (characteristic %in% c("Participant-days", "Participant time")) {
        return(paste("The earlier cell combined placement-specific data. The updated cell", "reports the whole available roster and placement-specific quantities", "across every recorded non-all-zero day."))
    }
    if (characteristic == "Declared non-wear") {
        return(paste("The earlier implementation accidentally reused the near-eye non-wear", "input for chest and used an unclear pooled denominator. The updated", "cell therefore reports near-eye wear-log off outside diary sleep only,", "using observed real minutes on available non-all-zero days."))
    }
    if (characteristic == "Screened days") {
        return(paste("The earlier chest complete-day count came from the wrong preparation", "stage. The updated cell shows only the final placement-specific result", "after the completeness and exact-all-zero screens."))
    }
    if (characteristic == "Civil photoperiod") {
        return(paste("The updated cell uses verified civil dawn/dusk context for the union of", "all available non-all-zero participant-days across the whole roster."))
    }
    if (characteristic == "Sleep-corrected midsleep on free days") {
        return(paste("The updated cell uses the whole participant roster and circular clock-time", "summaries. During rebuilding, a quantile-argument typo was found and", "repaired before final output."))
    }
    paste("The familiar characteristic is retained, but the updated value is based", "on normalized metadata for the whole participant roster and states its", "available-participant denominator.")
}

