function(metric_id) {
    if (metric_id == "mder_mean_of_viable_ratios") {
        return(paste("The MDER estimand is corrected to the arithmetic mean of viable", "one-minute melEDI/illuminance ratios. Both channels must be finite and", "strictly positive, and a day is retained with at least 720 viable", "ratios on the complete 1,440-minute local wall-clock grid."))
    }
    if (grepl("timing|midpoint", metric_id)) {
        return(paste("The earlier display treated clock time linearly. The updated display", "uses circular means and circular middle-50% intervals from the verified", "metric artifact; the rebuild's quantile-argument typo was repaired before", "these values were finalized."))
    }
    if (metric_id %in% c("interdaily_stability", "intradaily_variability")) {
        return(paste("The familiar metric is retained, but the updated participant-level", "value comes from the verified metric artifact and now reports participants", "and the underlying participant-days instead of an unlabeled n."))
    }
    paste("The familiar metric and site layout are retained. The updated value comes", "from the verified main near-eye metric artifact after the approved", "completeness and exact-all-zero rules and now labels observations,", "participants, and participant-days.")
}

function(previous, current) {
    previous <- as.data.frame(previous, stringsAsFactors = FALSE)
    previous[] <- lapply(previous, normalize_previous_cell)
    metric_map <- previous_table2_metric_map()
    site_labels <- normalize_previous_cell(unlist(previous[2L, 3:12]))
    old_rows <- dplyr::bind_rows(lapply(seq_len(nrow(metric_map)), function(i) {
        row <- metric_map$previous_row[[i]]
        data.frame(metric_id = metric_map$metric_id[[i]], reader_site = site_labels, previous_display = normalize_previous_cell(unlist(previous[row, 3:12])), stringsAsFactors = FALSE)
    }))
    dplyr::arrange(dplyr::select(dplyr::mutate(dplyr::left_join(dplyr::mutate(current, site = as.character(.data$site), current_display = .data$display), old_rows, by = c("metric_id", "reader_site")), comparison_status = dplyr::case_when(is.na(.data$previous_display) ~ "NOT_FOUND_IN_RENDER", .data$previous_display == .data$current_display ~ "DISPLAY_UNCHANGED", TRUE ~ "DISPLAY_CHANGED"), difference_reason = vapply(.data$metric_id, table2_difference_reason, character(1))), "category", "metric_order", 
        "metric_id", "table_name", "unit", "site", "reader_site", "previous_display", "current_display", "comparison_status", "difference_reason", "analysis_unit", "n_observations", "n_participants", "n_participant_days"), .data$metric_order, factor(.data$site, levels = replica_site_levels()))
}

function(quantity) {
    if (quantity == "combined_fraction") {
        return(paste("The updated total is the pooled fraction across all valid classified", "minutes, not an average of displayed state percentages."))
    }
    if (quantity %in% c("wake_fraction", "pre_sleep_fraction", "sleep_fraction")) {
        return(paste("The threshold is retained, but the result is now described as contextual", "rather than adherence. Its denominator is valid one-minute observations", "within the named diary state on updated main near-eye days."))
    }
    paste("The updated state share is divided by all eligible real minutes on updated", "main near-eye days; unclassified time is the explicit residual.")
}

