function(metric_values, metric_id) {
    contract <- replica_metric_contract()
    row <- contract[contract$metric_id == metric_id, , drop = FALSE]
    if (nrow(row) != 1L) 
        stop("Unknown thumbnail metric: ", metric_id, call. = FALSE)
    plot_data <- dplyr::mutate(dplyr::filter(metric_values, .data$placement == "near_eye", .data$metric_id == .env$metric_id, .data$finite, is.finite(.data$value)), site = factor(.data$site, levels = descriptive_site_order()), plot_value = .data$value)
    is_timing <- grepl("timing|midpoint", metric_id)
    use_symlog <- row$scaling[[1L]] == "Symlog"
    if (metric_id == "dose_time_sensitive_corrected_medi") {
        plot_data$plot_value <- plot_data$plot_value/1000
    }
    if (is_timing) {
        plot_data$plot_value <- unwrap_clock_for_panel(plot_data$plot_value, metric_id)
    }
    if (use_symlog) {
        symlog <- LightLogR::symlog_trans(base = 10, thr = 1, scale = 1)
        plot_data$plot_value <- symlog$transform(plot_data$plot_value)
    }
    plot <- ggplot2::ggplot(plot_data, ggplot2::aes(x = .data$plot_value)) + ggridges::geom_density_ridges(ggplot2::aes(y = .data$site, fill = .data$site), linewidth = 1, colour = NA, alpha = 0.5, from = min(plot_data$plot_value, na.rm = TRUE), to = max(plot_data$plot_value, na.rm = TRUE), show.legend = FALSE) + ggridges::geom_density_ridges(ggplot2::aes(y = .data$site, colour = .data$site), fill = NA, alpha = 1, linewidth = 3, quantile_lines = TRUE, quantiles = 2, vline_color = "red", linetype = 1, 
        from = min(plot_data$plot_value, na.rm = TRUE), to = max(plot_data$plot_value, na.rm = TRUE), show.legend = FALSE) + ggplot2::scale_fill_manual(values = descriptive_site_palette()) + ggplot2::scale_colour_manual(values = descriptive_site_palette()) + ggplot2::scale_x_continuous(expand = ggplot2::expansion(mult = c(0.04, 0.04))) + ggplot2::labs(x = NULL, y = NULL) + ggridges::theme_ridges(font_size = 34) + ggplot2::coord_flip(clip = "on") + ggplot2::theme_sub_plot(margin = ggplot2::margin(2, 
        2, 2, 2)) + ggplot2::theme_sub_axis_bottom(text = ggplot2::element_blank()) + ggplot2::theme_sub_axis_left(text = ggplot2::element_text(vjust = 0))
    plot
}

function(x) {
    x <- gsub("&", "&amp;", x, fixed = TRUE)
    x <- gsub("\"", "&quot;", x, fixed = TRUE)
    x <- gsub("<", "&lt;", x, fixed = TRUE)
    gsub(">", "&gt;", x, fixed = TRUE)
}

function(plot, metric_name) {
    image <- suppressMessages(gt::ggplot_image(plot, height = 72, aspect_ratio = 2.5))
    description <- paste(metric_name, "distribution by site. Exact numerical summaries are in the adjacent cells.")
    image <- sub("<img ", "<img alt=\"\" aria-hidden=\"true\" role=\"presentation\" ", image, fixed = TRUE)
