function(fraction, numerator, denominator, accessibility_label) {
    if (!all(is.finite(c(fraction, numerator, denominator)))) {
        return("Not estimable")
    }
    numerator <- format(round(numerator), big.mark = ",", scientific = FALSE)
    denominator <- format(round(denominator), big.mark = ",", scientific = FALSE)
    paste0("**", sprintf("%.1f%%", 100 * fraction), "**<br>", "<span aria-label='", numerator, " ", accessibility_label, " out of ", denominator, " total' style='color:grey;font-size:9px;white-space:nowrap'>", numerator, " / ", denominator, "</span>")
}

