function(metric_values, category) {
    data <- dplyr::mutate(dplyr::filter(metric_values, .data$placement == "near_eye", .data$manuscript_category == category, .data$finite), site = factor(.data$site, levels = rev(descriptive_site_order())), panel_label = paste0(.data$metric_label, "\n(", .data$display_unit, "; ", .data$analysis_unit, ")"))
    title <- dplyr::recode(category, `level-based` = "Level-based near-eye metric distributions", `duration-based` = "Duration-based near-eye metric distributions", `exposure-history-based` = "Exposure-history near-eye metric distributions", `spectrum-based` = "Spectrum-based near-eye metric distributions", `dynamics-based` = "Dynamics-based near-eye metric distributions", .default = category)
    plot <- ggplot2::ggplot(data, ggplot2::aes(x = .data$value, y = .data$site, fill = .data$site)) + ggplot2::geom_violin(scale = "width", trim = TRUE, linewidth = 0.25, colour = "#4A4A4A", alpha = 0.72, na.rm = TRUE) + ggplot2::geom_boxplot(width = 0.14, outlier.shape = NA, fill = "white", colour = "black", linewidth = 0.3, na.rm = TRUE) + ggplot2::facet_wrap(~panel_label, scales = "free_x", ncol = 2) + ggplot2::scale_fill_manual(values = descriptive_site_palette(), guide = "none") + ggplot2::labs(title = title, 
        subtitle = "Violin: full finite distribution; white box: median and middle 50%.", x = NULL, y = NULL, caption = "Sites are named on the axis, so interpretation does not rely on colour.") + theme_descriptive(8) + ggplot2::theme(axis.text.y = ggplot2::element_text(size = 6.7), strip.text = ggplot2::element_text(size = 7.2))
    if (category %in% c("level-based", "duration-based", "exposure-history-based")) {
        breaks <- switch(category, `duration-based` = c(0, 0.1, 1, 10, 24), `exposure-history-based` = c(0, 10, 100, 1000, 10000, 1e+05), c(0, 0.1, 1, 10, 100, 1000, 10000, 1e+05))
        labels <- function(x) {
            vapply(x, function(value) {
                if (is.na(value)) 
                  return(NA_character_)
                if (value == 0) 
                  return("0")
                if (value < 1) 
                  return(trimws(formatC(value, format = "fg", digits = 2)))
                if (value < 1000) {
                  return(trimws(formatC(value, format = "fg", digits = 3)))
                }
                if (value < 1e+06) {
                  return(paste0(trimws(formatC(value/1000, format = "fg", digits = 3)), "K"))
                }
                trimws(formatC(value, format = "e", digits = 1))
            }, character(1))
        }
        plot <- plot + ggplot2::scale_x_continuous(trans = LightLogR::symlog_trans(base = 10, thr = 1, scale = 1), breaks = breaks, labels = labels)
    }
    plot
}

function(x) {
    vapply(x, function(value) {
        if (is.na(value)) 
            return(NA_character_)
        if (value == 0) 
            return("0")
        if (value < 1) 
            return(trimws(formatC(value, format = "fg", digits = 2)))
        if (value < 1000) {
            return(trimws(formatC(value, format = "fg", digits = 3)))
        }
        if (value < 1e+06) {
            return(paste0(trimws(formatC(value/1000, format = "fg", digits = 3)), "K"))
        }
        trimws(formatC(value, format = "e", digits = 1))
    }, character(1))
}

