function(value, unit) {
    if (identical(unit, "clock time")) {
        return(format_clock_minute(value))
    }
    digits <- if (unit %in% c("lx", "lx·h")) 
        4L
    else 3L
    paste(format_number_compact(value, digits), unit)
}

