function(data, x = "clock_minute") {
    first <- data
    second <- data
    second[[x]] <- second[[x]] + 1440
    dplyr::bind_rows(first, second)
}

function(colour, fraction) {
    fraction <- pmax(0, pmin(1, fraction))
    if (length(colour) == 1L) 
        colour <- rep(colour, length(fraction))
    mapply(function(single_colour, weight) {
        rgb <- grDevices::col2rgb(single_colour)/255
        grDevices::rgb(rgb[[1L]] * weight, rgb[[2L]] * weight, rgb[[3L]] * weight)
    }, colour, fraction, USE.NAMES = FALSE)
}

function(protocol_asset_path) {
    if (!file.exists(protocol_asset_path)) {
        stop("Protocol image is unavailable: ", protocol_asset_path, call. = FALSE)
    }
    cowplot::ggdraw() + cowplot::draw_image(protocol_asset_path)
}

function(latitude, longitude) {
    sprintf("%.1f°%s, %.1f°%s", abs(latitude), ifelse(latitude >= 0, "N", "S"), abs(longitude), ifelse(longitude >= 0, "E", "W"))
}

