    ggplot2::ggplot() + ggplot2::geom_rect(data = data, ggplot2::aes(xmin = .data$xmin, xmax = .data$xmax, ymin = .data$ymin, ymax = .data$ymax, fill = .data$site), colour = NA, alpha = 0.92) + ggplot2::scale_y_continuous(breaks = seq_along(reader_levels), labels = reader_levels, limits = c(0.5, length(reader_levels) + 0.5), expand = ggplot2::expansion(mult = c(0, 0))) + ggplot2::scale_fill_manual(values = descriptive_site_palette(), guide = "none") + ggplot2::scale_x_date(date_breaks = "1 year", 
        date_labels = "%Y") + ggplot2::labs(x = "Collection dates", y = NULL) + cowplot::theme_cowplot() + ggplot2::theme(axis.text.x = ggplot2::element_text(angle = 0, hjust = 0.5), legend.position = "none")
}

function(collection_days) {
