    ggplot2::ggplot(data, ggplot2::aes(x = .data$photoperiod_hours, y = .data$reader_site, fill = .data$site, colour = .data$site)) + ggplot2::geom_boxplot(width = 0.25, fill = NA, linewidth = 0.5, outlier.shape = NA, position = ggplot2::position_nudge(y = -0.25), show.legend = FALSE) + ggridges::geom_density_ridges(bandwidth = 0.25, alpha = 0.68, scale = 1, colour = "black", linewidth = 0.45, show.legend = FALSE) + ggplot2::scale_x_continuous(breaks = 10:21, limits = range(data$photoperiod_hours, 
        na.rm = TRUE)) + ggplot2::scale_colour_manual(values = descriptive_site_palette()) + ggplot2::scale_fill_manual(values = descriptive_site_palette()) + ggplot2::labs(y = NULL, x = "Photoperiod (hours)") + cowplot::theme_cowplot() + ggplot2::guides(fill = "none", colour = "none")
}

function(state_source, placement, site = NULL) {
    context <- dplyr::filter(state_source, .data$placement == .env$placement)
    if (!is.null(site)) {
        context <- dplyr::filter(context, .data$site == .env$site)
    }
    dplyr::bind_rows(context, dplyr::mutate(context, xmin = .data$xmin + 1440, xmax = .data$xmax + 1440))
}

function(period_source, placement, site = NULL) {
    periods <- dplyr::filter(period_source, .data$placement == .env$placement)
    if (!is.null(site)) {
        periods <- dplyr::filter(periods, .data$site == .env$site)
    }
    expanded <- tidyr::crossing(periods, day_offset = c(0, 1440))
    list(night = dplyr::bind_rows(dplyr::transmute(expanded, dplyr::across(dplyr::everything()), xmin = .data$day_offset, xmax = .data$day_offset + .data$mean_civil_dawn_minute), dplyr::transmute(expanded, dplyr::across(dplyr::everything()), xmin = .data$day_offset + .data$mean_civil_dusk_minute, xmax = .data$day_offset + 1440)), sleep = dplyr::bind_rows(dplyr::transmute(expanded, dplyr::across(dplyr::everything()), xmin = .data$day_offset, xmax = .data$day_offset + .data$mean_sleep_end_minute), 
        dplyr::transmute(expanded, dplyr::across(dplyr::everything()), xmin = .data$day_offset + .data$mean_sleep_start_minute, xmax = .data$day_offset + 1440)))
}

function(data) {
    dplyr::mutate(dplyr::filter(data, .data$site != "Overall"), reader_site = factor(replica_site_label(.data$site), levels = unname(descriptive_site_reader_labels())))
}

function() {
    contract <- replica_metric_contract()
    panel_ids <- c("duration_above_1000", "duration_above_250_wake", "duration_below_10_pre_sleep", "duration_below_1_sleep_environment", "longest_bout_above_250", "interdaily_stability", "intradaily_variability", "dose_time_sensitive_corrected_medi", "daily_geometric_mean_medi", "m10_mean_medi", "mder_mean_of_viable_ratios", "m10_midpoint", "l10_midpoint", "first_timing_above_250", "last_timing_above_250", "mean_timing_above_250")
    contract[match(panel_ids, contract$metric_id), , drop = FALSE]
}

function(value, metric_id) {
    centers <- c(m10_midpoint = 840, l10_midpoint = 180, first_timing_above_250 = 540, last_timing_above_250 = 1080, mean_timing_above_250 = 810)
    center <- unname(centers[[metric_id]])
    (value - center + 720)%%1440 - 720 + center
}

function(x) {
    vapply(x, function(value) {
        if (!is.finite(value)) 
            return(NA_character_)
        if (value == 0) 
            return("0")
        if (abs(value) < 1) 
            return(trimws(formatC(value, format = "fg", digits = 2)))
        if (abs(value) < 1000) 
            return(trimws(formatC(value, format = "fg", digits = 3)))
        paste0(trimws(formatC(value/1000, format = "fg", digits = 3)), "K")
    }, character(1))
}

function(contract_row) {
    labels <- c(duration_above_1000 = "TAT1000 (HH:MM)", duration_above_250_wake = "TAT250,wake (HH:MM)", duration_below_10_pre_sleep = "TBT10,pre-sleep (HH:MM)", duration_below_1_sleep_environment = "TBT1,sleep env. (HH:MM)", longest_bout_above_250 = "PAT250 (HH:MM)", interdaily_stability = "IS (dimensionless)", intradaily_variability = "IV (dimensionless)", dose_time_sensitive_corrected_medi = "Corrected dose (klx·h)", daily_geometric_mean_medi = "Geometric mean (lx)", m10_mean_medi = "M10 mean (lx)", 
        l10_mean_medi = "L10 mean (lx)", mder_mean_of_viable_ratios = "MDER (dimensionless)", m10_midpoint = "M10 midpoint (HH:MM)", l10_midpoint = "L10 midpoint (HH:MM)", first_timing_above_250 = "First >250 lx (HH:MM)", last_timing_above_250 = "Last >250 lx (HH:MM)", mean_timing_above_250 = "Mean >250 lx timing (HH:MM)")
    metric_id <- contract_row$metric_id[[1L]]
    label <- unname(labels[[metric_id]])
    if (is.null(label)) 
        stop("No single-line metric label: ", metric_id, call. = FALSE)
    label
}

function(metric_values, contract_row, panel_index) {
    metric_id <- contract_row$metric_id[[1L]]
    data <- dplyr::mutate(dplyr::filter(metric_values, .data$placement == "near_eye", .data$metric_id == .env$metric_id, .data$finite, is.finite(.data$value)), reader_site = factor(replica_site_label(.data$site), levels = rev(unname(descriptive_site_reader_labels()))), plot_value = .data$value)
    is_duration <- grepl("duration|longest_bout", metric_id)
    is_timing <- grepl("timing|midpoint", metric_id)
    is_symlog <- metric_id %in% c("daily_geometric_mean_medi", "m10_mean_medi", "l10_mean_medi")
    if (metric_id == "dose_time_sensitive_corrected_medi") {
        data$plot_value <- data$plot_value/1000
    }
    if (is_timing) 
        data$plot_value <- unwrap_clock_for_panel(data$plot_value, metric_id)
    raw_range <- range(data$plot_value, na.rm = TRUE)
    symlog <- NULL
    symlog_breaks <- NULL
    if (is_symlog) {
        symlog <- LightLogR::symlog_trans(base = 10, thr = 1, scale = 1)
        data$plot_value <- symlog$transform(data$plot_value)
        candidates <- c(0, 1, 10, 100, 1000, 10000, 1e+05)
        symlog_breaks <- candidates[candidates == 0 | candidates <= raw_range[[2L]] * 1.05]
    }
    show_y <- panel_index %in% c(1L, 5L, 9L, 13L)
    range_x <- range(data$plot_value, na.rm = TRUE)
    plot <- ggplot2::ggplot(data, ggplot2::aes(x = .data$plot_value)) + ggplot2::geom_boxplot(ggplot2::aes(y = .data$reader_site, colour = .data$site), width = 0.25, fill = NA, linewidth = 0.2, outlier.size = 0.45, outlier.alpha = 0.65, outlier.stroke = 0.12, position = ggplot2::position_nudge(y = -0.25), show.legend = FALSE) + ggridges::geom_density_ridges(ggplot2::aes(y = .data$reader_site, fill = .data$site), linewidth = 0.32, colour = NA, alpha = 0.5, scale = 1, from = range_x[[1L]], to = range_x[[2L]], 
        show.legend = FALSE) + ggridges::geom_density_ridges(ggplot2::aes(y = .data$reader_site, colour = .data$site), fill = NA, alpha = 1, linewidth = 0.32, scale = 1, quantile_lines = TRUE, quantiles = 2, vline_color = "red", from = range_x[[1L]], to = range_x[[2L]], show.legend = FALSE) + ggplot2::scale_fill_manual(values = descriptive_site_palette()) + ggplot2::scale_colour_manual(values = descriptive_site_palette()) + ggplot2::guides(fill = "none", colour = "none") + ggplot2::labs(y = NULL, 
        x = metric_panel_axis_label(contract_row)) + ggridges::theme_ridges() + ggplot2::coord_cartesian(clip = "off") + ggplot2::theme(plot.margin = ggplot2::margin(r = 6, t = 8, b = 4, l = 2), axis.line = ggplot2::element_line(linewidth = 0.22), axis.ticks = ggplot2::element_line(linewidth = 0.22), axis.text.y = if (show_y) {
        ggplot2::element_text(vjust = 0, size = 6.5)
    }
    else {
        ggplot2::element_blank()
    }, axis.text.x = ggplot2::element_text(size = 6.5), axis.title.x = ggplot2::element_text(size = 6.5, lineheight = 0.95, margin = ggplot2::margin(t = 5)))
    if (is_duration) {
        plot <- plot + ggplot2::scale_x_continuous(breaks = scales::breaks_pretty(n = 3), labels = format_duration_hours)
    }
    else if (is_timing) {
        width <- if (diff(range_x) > 14 * 60) 
            480
        else 240
        plot <- plot + ggplot2::scale_x_continuous(breaks = scales::breaks_width(width), labels = function(x) format_clock_minute(x%%1440))
    }
    else if (is_symlog) {
        if (length(symlog_breaks) > 4L) {
            keep <- unique(round(seq(1, length(symlog_breaks), length.out = 4)))
            symlog_breaks <- symlog_breaks[keep]
        }
        plot <- plot + ggplot2::scale_x_continuous(breaks = symlog$transform(symlog_breaks), labels = replica_compact_axis(symlog_breaks))
    }
    else {
        plot <- plot + ggplot2::scale_x_continuous(breaks = scales::breaks_pretty(n = 3))
    }
    plot
}

function(metric_values) {
    contract <- replica_metric_panel_contract()
    panels <- lapply(seq_len(nrow(contract)), function(index) {
        make_metric_replica_panel(metric_values, contract[index, , drop = FALSE], index)
    })
    patchwork::wrap_plots(panels, ncol = 4) + patchwork::plot_annotation(tag_levels = "A") & ggplot2::theme(plot.tag = ggplot2::element_text(face = "bold", size = 7.5))
}
